import os
from pathlib import Path

AUDIO = {'.mp3','.flac','.wav','.aiff','.aif','.m4a','.ogg','.opus'}
NOISE = {'.jpg','.jpeg','.png','.webp','.gif','.bmp','.ds_store'}
root = Path.home() / 'Music Unsorted'
removed_files = removed_dirs = 0
for dirpath, dirs, files in os.walk(root, topdown=False):
    d = Path(dirpath)
    has_audio = any(f.lower().endswith(tuple(AUDIO)) for f in files)
    if not has_audio:
        for f in files:
            if Path(f).suffix.lower() in NOISE or f == '.DS_Store':
                (d / f).unlink(missing_ok=True)
                removed_files += 1
    try:
        d.rmdir()
        removed_dirs += 1
    except OSError:
        pass
print(f'✅ Removed {removed_files} non-audio files and {removed_dirs} empty folders from Music Unsorted')
"
